'use strict';
const fs=require('fs');const path=require('path');const cp=require('child_process');const{chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href;
const OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output'),SHOTS=path.join(OUT,'P14_FULLHD_SCREENSHOTS');fs.mkdirSync(SHOTS,{recursive:true});
const COMPANY_ID=27;
const USERS={OWNER:{id:16,username:'p14_owner_260804221827'},SENIOR_LOGIST:{id:17,username:'p14_senior_260804221827'},LOGIST_1:{id:18,username:'p14_logist1_260804221827'},LOGIST_2:{id:19,username:'p14_logist2_260804221827'}};
function runtimeCreds(){const e=process.env.P11_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}
function superadmin(){return runtimeCreds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function loginTry(browser,u,pw){const context=await browser.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),page=await context.newPage();let ok=false;try{await page.goto(U('login'),{waitUntil:'domcontentloaded',timeout:45000});await page.locator('input[name="username"],input[name="email"],input[type="email"],input[type="text"]').first().fill(u);await page.locator('input[type="password"]').first().fill(pw);await Promise.all([page.waitForLoadState('domcontentloaded',{timeout:15000}).catch(()=>{}),page.locator('button[type="submit"],input[type="submit"]').first().click()]);await page.waitForTimeout(500);ok=!/\/login(?:[/?#]|$)/i.test(page.url())}catch{}return{ok,context,page}}
function candidates(text,vals,u){const a=[...vals];for(const m of String(text||'').matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==u&&!x.includes('@example.test')&&!/^\+?7\d{10}$/.test(x)&&!/^[a-f0-9]{64}$/i.test(x))}
async function resetAndLogin(browser,role){const sa=superadmin();const sx=await loginTry(browser,sa.username,sa.password);if(!sx.ok)throw Error('superadmin reset session failed');await sx.page.goto(U(`superadmin/companies/${COMPANY_ID}/users`),{waitUntil:'domcontentloaded',timeout:45000});const meta=USERS[role];const action=role==='OWNER'?`/superadmin/companies/${COMPANY_ID}/owner/reset-password`:`/superadmin/companies/${COMPANY_ID}/users/logists/${meta.id}/reset-password`;const form=sx.page.locator(`form[action$="${action}"]`).first();if(!(await form.count()))throw Error(`reset form unavailable ${role}`);const nav=sx.page.waitForNavigation({waitUntil:'domcontentloaded',timeout:30000});await form.evaluate(f=>HTMLFormElement.prototype.submit.call(f));await nav;const vals=await sx.page.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(n=>n.value||n.getAttribute('data-password')||n.textContent||'').filter(Boolean));const list=candidates(await sx.page.locator('body').innerText().catch(()=>''),vals,meta.username);await sx.context.close();for(const candidate of list){const t=await loginTry(browser,meta.username,candidate);if(t.ok){for(let i=0;i<list.length;i++)list[i]='';return t}await t.context.close()}throw Error(`password verification failed ${role}`)}
const routes={
SUPERADMIN:['superadmin/companies','superadmin/db-usage','superadmin/deleted-data',`superadmin/companies/${COMPANY_ID}`,`superadmin/companies/${COMPANY_ID}/edit`,`superadmin/companies/${COMPANY_ID}/owner`,`superadmin/companies/${COMPANY_ID}/users`,`superadmin/companies/${COMPANY_ID}/directories`,`superadmin/companies/${COMPANY_ID}/documents`,`superadmin/companies/${COMPANY_ID}/access-grants`,`superadmin/companies/${COMPANY_ID}/clients`,`superadmin/companies/${COMPANY_ID}/contractors`,`superadmin/companies/${COMPANY_ID}/drivers`,`superadmin/companies/${COMPANY_ID}/vehicles`,`superadmin/companies/${COMPANY_ID}/crews`],
OWNER:['company/dashboard','company/clients','company/trips/linear','company/trips/departures','company/route-executors','company/contractors','company/drivers','company/vehicle-sets','company/logists','company/responsible-assignments','company/documents','company/finance/dashboard','company/finance/bank-accounts','company/finance/cash','company/finance/invoices','company/finance/operations','company/finance/payment-calendar','company/finance/reports/cash-flow','company/finance/reports/management-balance','company/finance/reports/payment-plan-fact','company/finance/settings/dds-categories','company/finance/settings/matching-rules'],
SENIOR_LOGIST:['company/dashboard','company/clients','company/trips/linear','company/trips/departures','company/route-executors','company/contractors','company/drivers','company/vehicle-sets','company/documents','company/finance/dashboard'],
LOGIST_1:['company/dashboard','company/clients','company/trips/linear','company/trips/departures','company/route-executors','company/contractors','company/drivers','company/vehicle-sets','company/documents','company/finance/dashboard'],
LOGIST_2:['company/dashboard','company/clients','company/trips/linear','company/trips/departures','company/route-executors','company/contractors','company/drivers','company/vehicle-sets','company/documents','company/finance/dashboard']};
function safe(s){return s.replace(/[^a-z0-9]+/gi,'_').replace(/^_+|_+$/g,'').slice(0,100)}
async function auditRole(session,role,result){const page=session.page;const rr={role,pages:[],loginPass:true};for(let i=0;i<routes[role].length;i++){const pth=routes[role][i],diag={consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[]};const oc=m=>{if(m.type()==='error')diag.consoleErrors.push(m.text())},oe=e=>diag.pageErrors.push(String(e.message||e)),of=q=>diag.requestFailures.push(`${q.method()} ${q.url()} ${q.failure()?.errorText||''}`),or=r=>{if(r.status()>=400)diag.httpFailures.push(`${r.status()} ${r.url()}`)};page.on('console',oc);page.on('pageerror',oe);page.on('requestfailed',of);page.on('response',or);let response=null,error=null;try{response=await page.goto(U(pth),{waitUntil:'domcontentloaded',timeout:45000});await page.waitForTimeout(350)}catch(e){error=e.name||'Error'}const metrics=await page.evaluate(()=>({title:document.title,h1:[...document.querySelectorAll('h1,h2,.page-title')].map(x=>(x.textContent||'').trim()).filter(Boolean).slice(0,5),bodyText:(document.body?.innerText||'').replace(/\s+/g,' ').slice(0,700),scrollWidth:document.documentElement.scrollWidth,clientWidth:document.documentElement.clientWidth,scrollHeight:document.documentElement.scrollHeight,viewport:{w:innerWidth,h:innerHeight}})).catch(()=>({}));const file=`P14_${role}_${String(i+1).padStart(2,'0')}_${safe(pth)}_1920x1080.png`;await page.screenshot({path:path.join(SHOTS,file),fullPage:false}).catch(()=>{});const denied=/доступ запрещ|forbidden|403/i.test(metrics.bodyText||'')||response?.status()===403;const finance=pth.startsWith('company/finance');const expectedDenied=(role==='SENIOR_LOGIST'||role.startsWith('LOGIST_'))&&finance;const pass=expectedDenied?denied:response?.status()===200&&!/\/login(?:[/?#]|$)/i.test(page.url())&&!denied;rr.pages.push({path:'/'+pth,httpStatus:response?.status()??null,finalUrl:page.url(),expected:expectedDenied?'DENY':'ALLOW',pass,error,screenshot:file,horizontalOverflow:(metrics.scrollWidth||0)>(metrics.clientWidth||0)+2,...metrics,...diag});page.off('console',oc);page.off('pageerror',oe);page.off('requestfailed',of);page.off('response',or)}result.roles.push(rr)}
function htmlEscape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
(async()=>{const result={status:'FAIL',generatedAt:new Date().toISOString(),configuration:{baseUrl:BASE,viewport:'1920x1080',deviceScaleFactor:1,locale:'ru-RU',timezone:'Europe/Moscow',companyId:COMPANY_ID,companyName:'UIUX TEST EXPEDITOR'},gates:{github:'PASS',archive:'PASS',browserSmoke:'PASS',superadminLogin:'PASS',tenantSetup:'PASS',dataSetup:'PASS_WITH_NONBLOCKING_LIMITATIONS'},syntheticData:{clientId:1,tempClientSoftDeletedId:2,contractorId:1,driverId:1,vehicleSetId:1,routeExecutorId:1,invoiceNumber:'P14-INV-001',ddsCode:'P14_AUDIT',cashPurpose:'P14 тестовое внесение'},confirmedBlockers:[{severity:'BLOCKER',area:'Рейсы',summary:'Создание линейного рейса невозможно',evidence:"SQLSTATE[23000] 1048 Column 'payment_due_type' cannot be null",uiValidationPassed:true,httpStatus:302}],roles:[],summary:{routes:0,pass:0,fail:0,allowExpected:0,denyExpected:0,consoleErrors:0,pageErrors:0,requestFailures:0,httpFailures:0,horizontalOverflow:0},errors:[]};let browser;const sessions=[];try{browser=await chromium.launch({headless:true});const sa=superadmin();if(!sa)throw Error('superadmin unavailable');const superSession=await loginTry(browser,sa.username,sa.password);if(!superSession.ok)throw Error('superadmin login failed');sessions.push(superSession);await auditRole(superSession,'SUPERADMIN',result);for(const role of ['OWNER','SENIOR_LOGIST','LOGIST_1','LOGIST_2']){const s=await resetAndLogin(browser,role);sessions.push(s);await auditRole(s,role,result)}for(const role of result.roles)for(const p of role.pages){result.summary.routes++;p.pass?result.summary.pass++:result.summary.fail++;p.expected==='ALLOW'?result.summary.allowExpected++:result.summary.denyExpected++;result.summary.consoleErrors+=p.consoleErrors.length;result.summary.pageErrors+=p.pageErrors.length;result.summary.requestFailures+=p.requestFailures.length;result.summary.httpFailures+=p.httpFailures.length;if(p.horizontalOverflow)result.summary.horizontalOverflow++}result.status=result.summary.fail===0?'P14_AUDIT_COMPLETE_READY_FOR_REVIEW':'P14_AUDIT_COMPLETE_WITH_FINDINGS';}catch(e){result.errors.push({name:e.name||'Error',message:String(e.message||e).slice(0,700)})}finally{for(const s of sessions)await s.context.close().catch(()=>{});if(browser)await browser.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_FULL_AUDIT.json'),JSON.stringify(result,null,2));let md=`# P14 ERP PLANEX — независимый UI/UX и функциональный аудит\n\n**Статус:** ${result.status}\n\n## Ворота\n- GitHub: ${result.gates.github}\n- Архив: ${result.gates.archive}\n- Browser smoke: ${result.gates.browserSmoke}\n- SUPERADMIN login: ${result.gates.superadminLogin}\n- Test tenant: ${result.gates.tenantSetup}\n\n## Итоги маршрутов\n- Проверено: ${result.summary.routes}\n- PASS: ${result.summary.pass}\n- FAIL: ${result.summary.fail}\n- Console errors: ${result.summary.consoleErrors}\n- Page errors: ${result.summary.pageErrors}\n- Request failures: ${result.summary.requestFailures}\n- HTTP >=400: ${result.summary.httpFailures}\n- Горизонтальное переполнение: ${result.summary.horizontalOverflow}\n\n## Блокирующий дефект\nСоздание линейного рейса после успешной UI-валидации завершается SQL integrity error: \`payment_due_type cannot be null\`. Production-код не изменялся.\n\n## Тестовые данные\n${Object.entries(result.syntheticData).map(([k,v])=>`- ${k}: ${v}`).join('\n')}\n\n## Матрица ролей\n`;for(const role of result.roles){md+=`\n### ${role.role}\n`;for(const p of role.pages)md+=`- ${p.pass?'PASS':'FAIL'} ${p.expected} ${p.httpStatus??'NO_STATUS'} ${p.path} — ${p.screenshot}\n`}md+=`\n## Ограничения\n- Рейс не создан из-за подтверждённого production-дефекта, а не из-за незаполненной формы.\n- Ранний дубликат тестовой компании, созданный correction loop до исправления ID detector, не используется и не изменялся.\n- Деплой, merge, production-код и старая /erp не затрагивались.\n`;fs.writeFileSync(path.join(OUT,'P14_DETAILED_REPORT.md'),md);let html=`<!doctype html><meta charset="utf-8"><title>P14 Screenshot Gallery</title><style>body{font-family:Arial;margin:24px;background:#eee}section{background:#fff;margin:18px 0;padding:16px}img{max-width:100%;border:1px solid #888}h2{position:sticky;top:0;background:#fff}</style><h1>P14 Screenshot Gallery</h1>`;for(const role of result.roles){html+=`<section><h2>${htmlEscape(role.role)}</h2>`;for(const p of role.pages)html+=`<h3>${p.pass?'PASS':'FAIL'} · ${htmlEscape(p.path)}</h3><p>HTTP ${p.httpStatus??'—'} · ${htmlEscape(p.expected)} · ${htmlEscape(p.finalUrl)}</p><img loading="lazy" src="P14_FULLHD_SCREENSHOTS/${encodeURIComponent(p.screenshot)}">`;html+='</section>'}fs.writeFileSync(path.join(OUT,'P14_SCREENSHOT_GALLERY.html'),html);fs.writeFileSync(path.join(OUT,'P14_FINAL_STATUS.txt'),`${result.status}\nROUTES=${result.summary.routes}\nPASS=${result.summary.pass}\nFAIL=${result.summary.fail}\nCONFIRMED_TRIP_BLOCKER=payment_due_type cannot be null\n`);const secretCheck=['test1234','PHPSESSID','storageState'];let leaked=[];for(const f of ['P14_FULL_AUDIT.json','P14_DETAILED_REPORT.md','P14_FINAL_STATUS.txt']){const text=fs.readFileSync(path.join(OUT,f),'utf8');for(const token of secretCheck)if(text.includes(token))leaked.push(`${f}:${token}`)}fs.writeFileSync(path.join(OUT,'P14_SECRET_SCAN.txt'),leaked.length?`FAIL\n${leaked.join('\n')}`:'PASS\nNo password, cookie, session ID or storageState persisted.\n');try{cp.execFileSync('zip',['-qr','P14_AUDIT_FINAL.zip','.','-x','P14_AUDIT_FINAL.zip'],{cwd:OUT})}catch(e){result.errors.push({name:'ZipError',message:String(e.message).slice(0,300)})}console.log(`P14_FULL_AUDIT=${result.status}`);process.exitCode=result.status==='FAIL'?1:0}})();
